import{c as e,J as a,h as r,k as i}from"./chunks/framework.WgZQdPFo.js";const h=JSON.parse('{"title":"Property & Resources","description":"Tracking long-term machinery, real estate, vehicles, and capital resources with fractional ownership and depreciation.","frontmatter":{"title":"Property & Resources","description":"Tracking long-term machinery, real estate, vehicles, and capital resources with fractional ownership and depreciation.","order":19},"headers":[],"relativePath":"docs/spaces/moy-kapital/property.md","filePath":"docs/spaces/moy-kapital/property.md"}'),o={name:"docs/spaces/moy-kapital/property.md"};function n(s,t,l,p,c,d){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="property-resources" tabindex="-1">Property &amp; Resources <a class="header-anchor" href="#property-resources" aria-label="Permalink to &quot;Property &amp; Resources&quot;">​</a></h1><p>The <strong>Property &amp; Resources</strong> tab serves as a permanent physical registry of long-term assets owned by the craftsman outside the active inventory of the workshop: precision skiving machines, heavy-duty sewing equipment, CNC laser cutters, commercial vehicles, workshop real estate, and strategic stockpiles of rare raw materials.</p><hr><h2 id="why-track-long-term-property-separately" tabindex="-1">Why Track Long-Term Property Separately <a class="header-anchor" href="#why-track-long-term-property-separately" aria-label="Permalink to &quot;Why Track Long-Term Property Separately&quot;">​</a></h2><p>Unlike consumable raw materials in the workshop (which are immediately expensed upon product manufacturing), major machinery and real estate transfer their value over years or serve as foundational equity backing your enterprise.</p><p>Logging property in the personal capital contour addresses three critical needs:</p><ol><li><strong>Accurate Net Worth Computation:</strong> your true net worth includes the fair market value of your machines, vehicles, and real estate, not just bank deposits.</li><li><strong>Fractional Ownership Tracking:</strong> if heavy equipment or studio space was purchased jointly with a partner 50/50, OmniCraft ERP accounts strictly for your exact share.</li><li><strong>Depreciation &amp; Maintenance Planning:</strong> monitoring physical wear and salvage values enables timely capital reserve planning for machinery upgrades.</li></ol><hr><h2 id="property-card-parameters" tabindex="-1">Property Card Parameters <a class="header-anchor" href="#property-card-parameters" aria-label="Permalink to &quot;Property Card Parameters&quot;">​</a></h2><p>When adding an asset to the property registry, you configure:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Example Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Asset Name</strong></td><td style="text-align:left;">Clear identifying title</td><td style="text-align:left;">Fortuna SAS Skiving Machine</td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;">Property classification</td><td style="text-align:left;">Machinery &amp; Equipment</td></tr><tr><td style="text-align:left;"><strong>Initial Cost</strong></td><td style="text-align:left;">Acquisition and setup expense</td><td style="text-align:left;">$$4,500$</td></tr><tr><td style="text-align:left;"><strong>Current Fair Valuation</strong></td><td style="text-align:left;">Realistic secondary market price</td><td style="text-align:left;">$$4,000$</td></tr><tr><td style="text-align:left;"><strong>Ownership Share, %</strong></td><td style="text-align:left;">Your equity percentage in the asset</td><td style="text-align:left;">$100%$ (or $50%$ with a partner)</td></tr><tr><td style="text-align:left;"><strong>Useful Lifespan</strong></td><td style="text-align:left;">Expected service duration</td><td style="text-align:left;">$60\\text{ months}$ (5 years)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Operational condition</td><td style="text-align:left;">In Service / Backup / In Storage</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Fractional Ownership Mathematics</p><p>When an asset is co-owned, its contribution to your consolidated Net Worth is factored proportionally: $$\\text{Capital Contribution} = \\text{Current Valuation} \\times \\frac{\\text{Ownership Share}}{100%}$$</p></div><hr><h2 id="depreciation-market-revaluation" tabindex="-1">Depreciation &amp; Market Revaluation <a class="header-anchor" href="#depreciation-market-revaluation" aria-label="Permalink to &quot;Depreciation &amp; Market Revaluation&quot;">​</a></h2><p>Physical equipment experiences wear over time, while real estate values may appreciate. OmniCraft ERP supports two methods to maintain accurate figures:</p><ol><li><strong>Straight-Line Depreciation:</strong> gradual linear amortization across the defined useful lifespan.</li><li><strong>Market Revaluation:</strong> periodic manual adjustment of the &quot;Current Fair Valuation&quot; field during annual workshop inventory reviews.</li></ol><div class="tip custom-block"><p class="custom-block-title">Realistic Liquidation Values</p><p>Record conservative liquidation values—the amount you could realistically recover within two to three weeks if you needed to free up capital urgently.</p></div>',17)])])}const y=e(o,[["render",n]]);export{h as __pageData,y as default};
